import io,gzip,base64,zipfile
import pandas as pd,numpy as np,streamlit as st

st.set_page_config(page_title="V6.12 Gerçek Blok İsabeti",page_icon="🎯",layout="wide")
st.title("🎯 V6.12 — GERÇEK ARDIŞIK BLOK / SAYI İSABET PROFESÖRÜ")
st.success("ZERO-UPLOAD — 161 güçlü sinyal + V6.1 gerçek pair kimlikleri gömülü.")
st.caption("Bu kez hareket doğruluğu değil, çekilişten ÖNCE seçilen gerçek ardışık çiftlerin H sonucunda aynen oluşup oluşmadığı ölçülür.")

P=""""""
G=""""""

@st.cache_data
def load():
    p=pd.read_csv(io.BytesIO(gzip.decompress(base64.b64decode(P))))
    g=pd.read_csv(io.BytesIO(gzip.decompress(base64.b64decode(G))))
    return p,g

p,g=load()

# PRE-H candidate score. H/HIT columns are NEVER used in candidate ranking.
# Prefer pair states that are alive/near-active in H1 and have stronger pre-state evidence.
def pre_score(r):
    s=0.0
    state=str(r.get("pre_state",""))
    if state=="11": s+=4
    elif state in ("01","10"): s+=3
    elif state=="00": s+=1
    s += 0.7*float(r.get("pre_sum",0))
    s += 0.25*float(r.get("pre_total_blocks",0))
    # Q2 frozen gate is pre-H by definition; modest support only.
    s += 1.0*float(r.get("Q2_GATE_FROZEN",0))
    return s

p["pre_score"]=p.apply(pre_score,axis=1)

# exact pair identity
p["pair_key"]=p.apply(lambda r:f"{int(r.a)}-{int(r.b)}",axis=1)

rows=[]
for d,grp in p.groupby("draw_no"):
    # unique concrete pairs, rank from PRE-H only
    q=grp.sort_values(["pre_score","a","b"],ascending=[False,True,True]).drop_duplicates("pair_key")
    # Evaluate fixed top-K menus; this is an audit, not a claim of optimized future performance.
    for k in [1,2,3,4,5]:
        sel=q.head(k)
        hits=int(sel.HIT.sum())
        rows.append({"draw_no":int(d),"K":k,"predicted_pairs":len(sel),"pair_hits":hits,
                     "all_pairs_hit":int(len(sel)>0 and hits==len(sel)),
                     "at_least_one":int(hits>0)})
res=pd.DataFrame(rows)

summary=(res.groupby("K").agg(
    draws=("draw_no","count"),
    predicted_pairs=("predicted_pairs","sum"),
    exact_pair_hits=("pair_hits","sum"),
    draws_at_least_one=("at_least_one","sum"),
    draws_all_selected_hit=("all_pairs_hit","sum")).reset_index())
summary["pair_precision"]=summary.exact_pair_hits/summary.predicted_pairs
summary["draw_hit_rate"]=summary.draws_at_least_one/summary.draws
summary["all_selected_rate"]=summary.draws_all_selected_hit/summary.draws

st.subheader("GERÇEK İSABET — hareket değil")
st.dataframe(summary,use_container_width=True,hide_index=True)

# Detailed top-3 concrete predictions, easier to interpret.
detail=[]
for d,grp in p.groupby("draw_no"):
    q=grp.sort_values(["pre_score","a","b"],ascending=[False,True,True]).drop_duplicates("pair_key").head(3)
    for rank,(_,r) in enumerate(q.iterrows(),1):
        detail.append({"draw_no":int(d),"rank":rank,"pair":r.pair_key,
                       "pre_state":r.pre_state,"pre_score":r.pre_score,
                       "actual_exact_pair_hit":int(r.HIT)})
detail=pd.DataFrame(detail)
st.subheader("İlk 3 gerçek çift — olay olay")
st.dataframe(detail,use_container_width=True,hide_index=True)

st.warning("Bu ilk sayı/blok katmanı bir BASELINE'dır. Aynı 161 olay üzerinde hangi PRE-H pair özelliklerinin gerçek pair isabetini artırdığını sonraki aşamada kronolojik walk-forward ile öğreneceğiz; burada hareket %94'ünü sayı isabeti diye kullanmıyoruz.")

bio=io.BytesIO()
with zipfile.ZipFile(bio,"w",zipfile.ZIP_DEFLATED) as z:
    z.writestr("00_MANIFEST.txt","V6.12 GERCEK BLOK ISABET BASELINE\nHareket accuracy degil. PRE-H skorla secilen somut ardışık pairlerin H'de exact HIT sonucu.\n")
    z.writestr("01_REAL_PAIR_PREDICTION_AUDIT.csv",res.to_csv(index=False).encode("utf-8-sig"))
    z.writestr("02_REAL_PAIR_SUMMARY.csv",summary.to_csv(index=False).encode("utf-8-sig"))
    z.writestr("03_TOP3_PAIR_DETAIL.csv",detail.to_csv(index=False).encode("utf-8-sig"))
st.download_button("⬇️ V6.12 GERÇEK BLOK İSABET — TEK ZIP",bio.getvalue(),"HIZLI_ON_V6_12_GERCEK_BLOK_ISABET.zip","application/zip",use_container_width=True)
